  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
vec4 CCFragOutput (vec4 color) {
  return color;
}
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D mainTexture;
   uniform vec4 splitParams;
vec4 frag () {
  vec2 uv = v_uv;
  float side = splitParams.x;
  if (side < 0.5) {
    uv.x *= 0.5;
  } else {
    uv.x = 0.5 + uv.x * 0.5;
  }
  vec4 color = CCSampleWithAlphaSeparated(mainTexture, uv) * v_color;
  return CCFragOutput(color);
